svg.script:
(async () => {
  const status = document.getElementById("status");
  if (location.protocol !== "https:" || !navigator.serviceWorker) {
    throw new Error("This starter requires HTTPS and a browser that supports service workers.");
  }

  const scope = "/gh/RubyStation/cyralune@main/nyx-static/";
  const workerUrl = new URL("cyralune-worker.js", location.href);
  await navigator.serviceWorker.register(workerUrl.href, {
    scope,
    updateViaCache: "none",
  });

  await navigator.serviceWorker.ready;

  if (!navigator.serviceWorker.controller) {
    await new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error("The browser did not finish setup. Reload this starter to retry."));
      }, 15000);
      const controlled = () => {
        clearTimeout(timer);
        resolve();
      };
      navigator.serviceWorker.addEventListener("controllerchange", controlled, { once: true });
      if (navigator.serviceWorker.controller) controlled();
    });
  }

  status.textContent = "Opening Cyralune…";
  location.replace(new URL("studies.html", location.href).href);
})().catch((error) => {
  document.getElementById("status").textContent = "Setup could not finish: " + error.message;
});
